arguments.command:
cd /tmp/sv-d7b243c3de8743f6ae6ca4a60953a82a && \
# Get proper function lookup - find functions that contain these addresses
nm -n libmonosgen-2.0.so.dbg 2>/dev/null | grep -i " [tT] " | awk '
{
  addr=strtonum("0x"$1)
  if (addr <= 0x2f4b20) { last_b20_addr=$1; last_b20_sym=$3 }
  if (addr <= 0x2f4c84) { last_c84_addr=$1; last_c84_sym=$3 }
}
END {
  print "0x2f4b20 is in: " last_b20_sym " (starts at 0x" last_b20_addr ")"
  print "0x2f4c84 is in: " last_c84_sym " (starts at 0x" last_c84_addr ")"
}'

